INSERT INTO evidence_notes(note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES
('N062-01','CN0030','S062-01','报告期运行及排口','年报pp76–77','2024母公司排放口1个，间歇排放；自建站→西安市第八污水厂。原表总镉0、总镍0–0.07mg/L及0.0033t/a；铜川另表不重复。2020许可至2025-07-26，续证待核；报告未披露站能力。PDF截图超时，按正文。','WEB_COMPANY','WEB_TEXT','2026-11-28'),
('N062-02','CN0095','S062-02','项目核准与投资','榕发改审批〔2026〕18号第1–4条','2026-02-03核准，项目代码2510-350100-04-01-943377，总投资5294.34万元；回收36t/a及4800kg/a以钌计制造与旧记录一致，不重复产能。非污水投资或环保验收；原环评PDF返回404。','WEB_PRIMARY','WEB_TEXT','2026-11-28'),
('N062-03','CN0207','S062-03','验收报告公示','正文公示时间及附件','2026-06-01至26日验收报告公示；附件跳注册，未判验收通过。联系人仅公开姓氏/称谓且电话遮挡，不猜私人号码；公开办公电话另取官网。','WEB_SECONDARY','WEB_TEXT','2026-11-28'),
('N062-04','CN0250','S062-05','新许可证及SCR边界','公告〔2026〕33号','许可编号6523270067，2026-07-22至2031-07-21；总46万t/a仅HW48（废炭渣6万、大修渣35万、铝灰渣5万），不含HW50。不能用该许可证实SCR生产或否定另有许可；2021设计10000m³/a SCR仍待验收。','WEB_PRIMARY','WEB_TEXT','2026-11-28'),
('N062-05','CN0269','S062-06','2024年度危废表','披露转载危废产生处置表','NaOH废包装0.0805t；重整废催化剂筛分0.3655t、加氢8.8645t、有机溶剂3.8745t；首项催化剂筛分处置0.3655t，其余对应表列0。为固废产生/处置，不是接收量、废水或废水污泥。报告称2023建成后生产正常与旧2025披露一致；联系方式遮挡未猜。','WEB_SECONDARY','WEB_TEXT','2026-11-28'),
('N062-06','CN0298','S042-05','排口及设计浓度','表5.2-11/13/14、8.5.2','DW001隔油沉淀，DW002化粪池；表5.2-14出水预计浓度分别录入；8.5.2的环境排放COD50是园区末端总量控制口径，不能替代厂区DW001。3150m³/a与COD0.414t/a/120mg/L不闭合，保留。截图405，按正文。','WEB_PRIMARY','WEB_TEXT','2026-11-28'),
('N062-07','CN0016','S062-08','新项目公示','企业官网公示及新闻目录','2026-06-30征求意见稿，官网新闻目录另列9月20日报批前公示。建设主体润和催化剂（四川）有限公司，不能认作现有乐山基地同一处理站；报告附件未取。','WEB_COMPANY','WEB_TEXT','2026-11-28'),
('N062-08','CN0133','S062-09','生产项目进度','2026-06-01政府报道','2026-05-29一期投产仪式，二期仍待建设；不能证明全部设计水处理设施已安装或实际流量。','WEB_PRIMARY','WEB_TEXT','2026-11-28'),
('N062-09','CN0115','turn106948search90','历史验收实测及去向','表9.2-8 p97（截图核证）、§10.3.6及p69审批落实对照','2023-11-09/10各4样品、13指标，共104原始测项（24 ND）；全盐量1300–1340mg/L，COD27–35mg/L。报告核算COD1.17t/a、NH3-N0.083t/a，非全年计量。综合站排汶上清泉水务；不由浓度反推实际水量或将共享出口认作催化剂单线。报告网页标题与正文不一致，以截图页眉及正文为准。','WEB_COMPANY','WEB_TEXT','2026-11-28'),
('N062-10','CN0125','S062-10','产销量及环保设备在建工程','2025年报产销量表及财务附注在建工程','催化剂实际产47284.52m³、销46661.14m³；三期环保设备（废气/废水合并）预算400万元、期末在建3345132.74元，累计83.63%，进度80%，未转固定资产。混合环保设备，不能拆为纯污水投资或实际运行费用。','WEB_COMPANY','WEB_TEXT','2026-11-28');
